-- SDK tables generated by Better Auth 1.7.14 and verified in isolated G2/G3 fixtures.
-- Applied only by the explicit MCP migration; nullable SDK session references require independent grants.
create table `mcp_oauth_client` (`id` varchar(36) not null primary key, `clientId` varchar(255) not null unique, `clientSecret` text, `clientDiscoveryId` text, `disabled` boolean, `skipConsent` boolean, `enableEndSession` boolean, `subjectType` text, `scopes` json, `clientCredentialsScopes` json, `userId` varchar(36) references `user` (`id`) on delete cascade, `createdAt` timestamp(3), `updatedAt` timestamp(3), `name` text, `uri` text, `icon` text, `contacts` json, `tos` text, `policy` text, `softwareId` text, `softwareVersion` text, `softwareStatement` text, `redirectUris` json not null, `postLogoutRedirectUris` json, `backchannelLogoutUri` text, `backchannelLogoutSessionRequired` boolean, `tokenEndpointAuthMethod` text, `applicationType` text, `jwks` text, `jwksUri` text, `grantTypes` json, `responseTypes` json, `requirePKCE` boolean, `dpopBoundAccessTokens` boolean, `referenceId` text, `metadata` json);

create table `mcp_oauth_resource` (`id` varchar(36) not null primary key, `identifier` varchar(255) not null unique, `name` text not null, `accessTokenTtl` integer, `refreshTokenTtl` integer, `signingAlgorithm` text, `signingKeyId` text, `allowedScopes` json, `customClaims` json, `dpopBoundAccessTokensRequired` boolean, `disabled` boolean, `createdAt` timestamp(3), `updatedAt` timestamp(3), `policyVersion` integer, `metadata` json);

create table `mcp_oauth_client_resource` (`id` varchar(36) not null primary key, `clientId` varchar(191) not null references `mcp_oauth_client` (`clientId`) on delete cascade, `resourceId` varchar(191) not null references `mcp_oauth_resource` (`identifier`) on delete cascade, `metadata` json, `createdAt` timestamp(3));

create table `mcp_oauth_refresh_token` (`id` varchar(36) not null primary key, `token` varchar(255) not null unique, `clientId` varchar(36) not null references `mcp_oauth_client` (`clientId`) on delete cascade, `sessionId` varchar(36) references `session` (`id`) on delete set null, `userId` varchar(36) not null references `user` (`id`) on delete cascade, `referenceId` text, `authorizationCodeId` varchar(255), `resources` json, `requestedUserInfoClaims` json, `expiresAt` timestamp(3) not null, `createdAt` timestamp(3) not null, `revoked` timestamp(3), `rotatedAt` timestamp(3), `rotationReplayResponse` text, `rotationReplayExpiresAt` timestamp(3), `authTime` timestamp(3), `confirmation` json, `scopes` json not null);

create table `mcp_oauth_access_token` (`id` varchar(36) not null primary key, `token` varchar(255) not null unique, `clientId` varchar(36) not null references `mcp_oauth_client` (`clientId`) on delete cascade, `sessionId` varchar(36) references `session` (`id`) on delete set null, `userId` varchar(36) references `user` (`id`) on delete cascade, `referenceId` text, `authorizationCodeId` varchar(255), `resources` json, `requestedUserInfoClaims` json, `refreshId` varchar(36) references `mcp_oauth_refresh_token` (`id`) on delete cascade, `expiresAt` timestamp(3) not null, `createdAt` timestamp(3) not null, `revoked` timestamp(3), `confirmation` json, `scopes` json not null);

create table `mcp_oauth_consent` (`id` varchar(36) not null primary key, `clientId` varchar(36) not null references `mcp_oauth_client` (`clientId`) on delete cascade, `userId` varchar(36) references `user` (`id`) on delete cascade, `referenceId` text, `resources` json, `requestedUserInfoClaims` json, `scopes` json not null, `createdAt` timestamp(3) not null, `updatedAt` timestamp(3) not null);

create table `mcp_oauth_client_assertion` (`id` varchar(36) not null primary key, `expiresAt` timestamp(3) not null);

create index `mcp_oauth_client_userId_idx` on `mcp_oauth_client` (`userId`);

create index `mcp_oauth_client_resource_clientId_idx` on `mcp_oauth_client_resource` (`clientId`);

create index `mcp_oauth_client_resource_resourceId_idx` on `mcp_oauth_client_resource` (`resourceId`);

create index `mcp_oauth_refresh_token_clientId_idx` on `mcp_oauth_refresh_token` (`clientId`);

create index `mcp_oauth_refresh_token_sessionId_idx` on `mcp_oauth_refresh_token` (`sessionId`);

create index `mcp_oauth_refresh_token_userId_idx` on `mcp_oauth_refresh_token` (`userId`);

create index `mcp_oauth_refresh_token_authorizationCodeId_idx` on `mcp_oauth_refresh_token` (`authorizationCodeId`);

create index `mcp_oauth_access_token_clientId_idx` on `mcp_oauth_access_token` (`clientId`);

create index `mcp_oauth_access_token_sessionId_idx` on `mcp_oauth_access_token` (`sessionId`);

create index `mcp_oauth_access_token_userId_idx` on `mcp_oauth_access_token` (`userId`);

create index `mcp_oauth_access_token_authorizationCodeId_idx` on `mcp_oauth_access_token` (`authorizationCodeId`);

create index `mcp_oauth_access_token_refreshId_idx` on `mcp_oauth_access_token` (`refreshId`);

create index `mcp_oauth_consent_clientId_idx` on `mcp_oauth_consent` (`clientId`);

create index `mcp_oauth_consent_userId_idx` on `mcp_oauth_consent` (`userId`);

create unique index `mcp_oauth_client_resource_clientId_resourceId_uidx` on `mcp_oauth_client_resource` (`clientId`, `resourceId`);
-- Application-owned grants and immutable invocation ownership.
-- Auth owns the session table: keep its public ID without a cross-module FK
-- which could erase the approval identity when a session is deleted.
CREATE TABLE mcp_grant (
  id CHAR(36) NOT NULL PRIMARY KEY,
  ownerId CHAR(36) NOT NULL,
  clientId VARCHAR(255) NOT NULL,
  approvalSessionId CHAR(36) NOT NULL,
  resource VARCHAR(512) NOT NULL,
  generation BIGINT UNSIGNED NOT NULL,
  workspaceId CHAR(36) NOT NULL,
  sourceId CHAR(36) NOT NULL,
  connectorId CHAR(36) NOT NULL,
  tables JSON NOT NULL,
  scopes JSON NOT NULL,
  revokedAt DATETIME(3) NULL,
  expiresAt DATETIME(3) NOT NULL,
  createdAt DATETIME(3) NOT NULL,
  INDEX mcp_grant_owner_page (ownerId, createdAt, id),
  INDEX mcp_grant_approval (ownerId, approvalSessionId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE mcp_grant_token (
  tokenHash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY,
  grantId CHAR(36) NOT NULL,
  issuedGeneration BIGINT UNSIGNED NOT NULL,
  CONSTRAINT mcp_grant_token_grant FOREIGN KEY (grantId) REFERENCES mcp_grant(id) ON DELETE RESTRICT,
  INDEX mcp_grant_token_family (grantId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE mcp_client (
 clientId VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY,
 ownerId CHAR(36) NOT NULL,
 name VARCHAR(80) NOT NULL,
 redirectUri VARCHAR(512) NOT NULL,
 mode VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 disabled TINYINT UNSIGNED NOT NULL DEFAULT 0,
 createdAt DATETIME(3) NOT NULL,
 INDEX mcp_client_owner(ownerId,createdAt)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE mcp_code (
 codeHash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY,
 grantId CHAR(36) NOT NULL,
 generation BIGINT UNSIGNED NOT NULL,
 expiresAt DATETIME(3) NOT NULL,
 used TINYINT UNSIGNED NOT NULL,
 INDEX mcp_code_expiry(expiresAt)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE mcp_local_domain (
 ownerId CHAR(36) NOT NULL PRIMARY KEY,
 clientId VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE mcp_invocation (
 id CHAR(36) NOT NULL PRIMARY KEY,
 ownerId CHAR(36) NOT NULL,
 grantId CHAR(36) NOT NULL,
 generation BIGINT UNSIGNED NOT NULL,
 commitment CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 bootId CHAR(36) NOT NULL,
 tool VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 state VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 approvalSessionId CHAR(36) NULL,
 taskId CHAR(36) NULL,
 taskNonce VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
 createdAt DATETIME(3) NOT NULL,
 expiresAt DATETIME(3) NOT NULL,
 INDEX mcp_invocation_owner(ownerId,createdAt),
 INDEX mcp_invocation_grant(grantId,state)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE mcp_schema_version (
 version INT NOT NULL PRIMARY KEY,
 checksum CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 shapeHash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
